<template>
  <div id="app" @click="closeAllOptions">
    <h1>나이 계산기</h1>
    <div class="input-container">
      <div class="select-group">
        <label>생년월일:</label>
        <div class="select-wrapper" @click.stop="toggleBirthDate(true)">
          <span>{{ birthDisplay }}</span>
          <div v-if="isBirthDateOpen" class="select-options" @click.stop>
            <div class="date-options-group">
              <select v-model="tempBirthYear" @change="updateTempBirthDate">
                <option value="" disabled>년도</option>
                <option v-for="year in years" :key="year" :value="year">
                  {{ year }}
                </option>
              </select>
              <select v-model="tempBirthMonth" @change="updateTempBirthDate">
                <option value="" disabled>월</option>
                <option v-for="month in 12" :key="month" :value="month">
                  {{ month }}월
                </option>
              </select>
              <select v-model="tempBirthDay" @change="updateTempBirthDate">
                <option value="" disabled>일</option>
                <option
                  v-for="day in tempDaysInBirthMonth"
                  :key="day"
                  :value="day"
                >
                  {{ day }}일
                </option>
              </select>
            </div>
            <button class="apply-btn" @click.stop="applyBirthDate">적용</button>
          </div>
        </div>
      </div>
      <div class="select-group">
        <label>기준일 (오늘):</label>
        <div class="select-wrapper" @click.stop="toggleTodayDate(true)">
          <span>{{ todayDisplay }}</span>
          <div v-if="isTodayDateOpen" class="select-options" @click.stop>
            <div class="date-options-group">
              <select v-model="tempTodayYear" @change="updateTempTodayDate">
                <option value="" disabled>년도</option>
                <option v-for="year in years" :key="year" :value="year">
                  {{ year }}
                </option>
              </select>
              <select v-model="tempTodayMonth" @change="updateTempTodayDate">
                <option value="" disabled>월</option>
                <option v-for="month in 12" :key="month" :value="month">
                  {{ month }}월
                </option>
              </select>
              <select v-model="tempTodayDay" @change="updateTempTodayDate">
                <option value="" disabled>일</option>
                <option
                  v-for="day in tempDaysInTodayMonth"
                  :key="day"
                  :value="day"
                >
                  {{ day }}일
                </option>
              </select>
            </div>
            <button class="apply-btn" @click.stop="applyTodayDate">적용</button>
          </div>
        </div>
      </div>
      <div class="button-group">
        <button class="reset-btn" @click="reset">초기화</button>
        <button class="calculate-btn" @click="calculateAge">계산하기</button>
      </div>
    </div>

    <div class="result-container" v-if="result">
      <h2>계산 결과</h2>
      <div class="result-box">
        <p><strong>만나이:</strong> {{ result.fullAge }}세</p>
        <p v-if="result.fullAge < 3">
          <strong>개월 수:</strong> {{ result.months }}개월
        </p>
        <p v-if="result.fullAge < 3">
          <strong>일 수:</strong> {{ result.days }}일
        </p>
        <p><strong>연나이:</strong> {{ result.yearAge }}세</p>
        <p><strong>한국나이:</strong> {{ result.koreanAge }}세</p>
        <p><strong>띠 (간지):</strong> {{ result.zodiac }}</p>
      </div>
    </div>
  </div>
</template>

<script>
import {
  differenceInYears,
  differenceInMonths,
  differenceInDays,
} from "date-fns";

export default {
  name: "App",
  data() {
    const defaultBirthDate = new Date(2024, 4, 2); // 2024년 5월 2일 (월은 0부터 시작하므로 4)
    const today = new Date();
    return {
      birthYear: defaultBirthDate.getFullYear(),
      birthMonth: defaultBirthDate.getMonth() + 1, // 1~12로 변환
      birthDay: defaultBirthDate.getDate(),
      todayYear: today.getFullYear(),
      todayMonth: today.getMonth() + 1, // 0부터 시작하므로 +1
      todayDay: today.getDate(),
      tempBirthYear: "",
      tempBirthMonth: "",
      tempBirthDay: "",
      tempTodayYear: "",
      tempTodayMonth: "",
      tempTodayDay: "",
      isBirthDateOpen: false,
      isTodayDateOpen: false,
      result: null,
    };
  },
  computed: {
    years() {
      return Array.from({ length: 151 }, (_, i) => 1925 + i); // 1925 ~ 2075년
    },
    daysInMonth() {
      if (!this.birthYear || !this.birthMonth) return 31;
      return new Date(this.birthYear, this.birthMonth, 0).getDate(); // 생일 월의 일수
    },
    todayDaysInMonth() {
      if (!this.todayYear || !this.todayMonth) return 31;
      return new Date(this.todayYear, this.todayMonth, 0).getDate(); // 기준일 월의 일수
    },
    tempDaysInBirthMonth() {
      if (!this.tempBirthYear || !this.tempBirthMonth) return 31;
      return new Date(this.tempBirthYear, this.tempBirthMonth, 0).getDate(); // 임시 생일 월의 일수
    },
    tempDaysInTodayMonth() {
      if (!this.tempTodayYear || !this.tempTodayMonth) return 31;
      return new Date(this.tempTodayYear, this.tempTodayMonth, 0).getDate(); // 임시 기준일 월의 일수
    },
    birthDisplay() {
      if (this.birthYear && this.birthMonth && this.birthDay) {
        return `${this.birthYear}년 ${this.birthMonth}월 ${this.birthDay}일`;
      }
      return "년 월 일";
    },
    todayDisplay() {
      if (this.todayYear && this.todayMonth && this.todayDay) {
        return `${this.todayYear}년 ${this.todayMonth}월 ${this.todayDay}일`;
      }
      return "년 월 일";
    },
  },
  methods: {
    toggleBirthDate(forceOpen = false) {
      if (forceOpen) {
        this.isBirthDateOpen = true;
      } else {
        this.isBirthDateOpen = !this.isBirthDateOpen;
      }
      this.isTodayDateOpen = false;
      this.tempBirthYear = this.birthYear;
      this.tempBirthMonth = this.birthMonth;
      this.tempBirthDay = this.birthDay;
    },
    toggleTodayDate(forceOpen = false) {
      if (forceOpen) {
        this.isTodayDateOpen = true;
      } else {
        this.isTodayDateOpen = !this.isTodayDateOpen;
      }
      this.isBirthDateOpen = false;
      this.tempTodayYear = this.todayYear;
      this.tempTodayMonth = this.todayMonth;
      this.tempTodayDay = this.todayDay;
    },
    closeAllOptions(event) {
      if (!event.target.closest(".select-wrapper")) {
        if (this.isBirthDateOpen) {
          this.applyBirthDate();
        }
        if (this.isTodayDateOpen) {
          this.applyTodayDate();
        }
        this.isBirthDateOpen = false;
        this.isTodayDateOpen = false;
      }
    },
    updateTempBirthDate() {
      this.tempBirthDay = Math.min(
        this.tempBirthDay || 1,
        this.tempDaysInBirthMonth
      );
    },
    updateTempTodayDate() {
      this.tempTodayDay = Math.min(
        this.tempTodayDay || 1,
        this.tempDaysInTodayMonth
      );
    },
    applyBirthDate() {
      if (!this.tempBirthYear || !this.tempBirthMonth || !this.tempBirthDay) {
        alert("생년월일을 모두 선택해주세요!");
        return;
      }
      const birthDate = new Date(
        this.tempBirthYear,
        this.tempBirthMonth - 1,
        this.tempBirthDay
      );
      if (isNaN(birthDate.getTime())) {
        alert("유효한 생년월일을 입력해주세요!");
        return;
      }
      this.birthYear = this.tempBirthYear;
      this.birthMonth = this.tempBirthMonth;
      this.birthDay = this.tempBirthDay;
      this.isBirthDateOpen = false;
      this.recalculateResult();
    },
    applyTodayDate() {
      if (!this.tempTodayYear || !this.tempTodayMonth || !this.tempTodayDay) {
        alert("기준일을 모두 선택해주세요!");
        return;
      }
      const todayDate = new Date(
        this.tempTodayYear,
        this.tempTodayMonth - 1,
        this.tempTodayDay
      );
      if (isNaN(todayDate.getTime())) {
        alert("유효한 기준일을 입력해주세요!");
        return;
      }
      this.todayYear = this.tempTodayYear;
      this.todayMonth = this.tempTodayMonth;
      this.todayDay = this.tempTodayDay;
      this.isTodayDateOpen = false;
      this.recalculateResult();
    },
    recalculateResult() {
      if (
        this.birthYear &&
        this.birthMonth &&
        this.birthDay &&
        this.todayYear &&
        this.todayMonth &&
        this.todayDay
      ) {
        this.calculateAge();
      }
    },
    handleEnterKey(event) {
      if (event.key === "Enter") {
        if (this.isBirthDateOpen) {
          this.applyBirthDate();
        } else if (this.isTodayDateOpen) {
          this.applyTodayDate();
        }
      }
    },
    calculateAge() {
      const today = new Date(
        this.todayYear,
        this.todayMonth - 1,
        this.todayDay
      );
      const birthDate = new Date(
        this.birthYear,
        this.birthMonth - 1,
        this.birthDay
      );

      if (today < birthDate) {
        alert("기준일은 생년월일보다 늦어야 합니다!");
        return;
      }

      const fullAge = differenceInYears(today, birthDate);
      const yearAge = today.getFullYear() - birthDate.getFullYear();
      const koreanAge = yearAge + 1;
      const zodiac = this.getZodiac(birthDate.getFullYear());

      let months = null;
      let days = null;

      if (fullAge < 3) {
        months = differenceInMonths(today, birthDate);
        days = differenceInDays(today, birthDate);
      }

      this.result = { fullAge, months, days, yearAge, koreanAge, zodiac };
    },
    getZodiac(year) {
      const zodiacs = [
        "쥐",
        "소",
        "호랑이",
        "토끼",
        "용",
        "뱀",
        "말",
        "양",
        "원숭이",
        "닭",
        "개",
        "돼지",
      ];
      return zodiacs[(year - 4) % 12];
    },
    reset() {
      const defaultBirthDate = new Date(2024, 4, 2);
      const today = new Date();
      this.birthYear = defaultBirthDate.getFullYear();
      this.birthMonth = defaultBirthDate.getMonth() + 1;
      this.birthDay = defaultBirthDate.getDate();
      this.todayYear = today.getFullYear();
      this.todayMonth = today.getMonth() + 1;
      this.todayDay = today.getDate();
      this.tempBirthYear = this.birthYear;
      this.tempBirthMonth = this.birthMonth;
      this.tempBirthDay = this.birthDay;
      this.tempTodayYear = this.todayYear;
      this.tempTodayMonth = this.todayMonth;
      this.tempTodayDay = this.todayDay;
      this.isBirthDateOpen = false;
      this.isTodayDateOpen = false;
      this.result = null;
    },
  },
  mounted() {
    document.addEventListener("keydown", this.handleEnterKey);
  },
  beforeUnmount() {
    document.removeEventListener("keydown", this.handleEnterKey);
  },
};
</script>

